window.LANG = localStorage.getItem("traffic-lang") === "en" ? "en" : "ru";

window.t = function (key, vars) {
  const d = window.I18N[window.LANG];
  let s = d[key] ?? window.I18N.ru[key] ?? key;
  if (vars) for (const k in vars) s = s.split("{" + k + "}").join(vars[k]);
  return s;
};

window.applyI18n = function (root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll("[data-i18n-ph]").forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll("[data-i18n-aria]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAria)); });
  root.querySelectorAll("[data-i18n-title]").forEach((el) => { el.title = t(el.dataset.i18nTitle); });
  document.documentElement.lang = window.LANG;
  document.title = window.LANG === "en" ? "Intellect X — Traffic Flows (prototype)" : "Интеллект X — Транспортные потоки (прототип)";
};
